INSERT OR IGNORE INTO academy_knowledge (id, kind, category, title_pl, title_en, content_pl, content_en, tags, source_ref) VALUES
('beginner:ZERO31-005','beginner','BIOS / UEFI','Analiza ustawień UEFI i kolejności bootowania','UEFI settings and boot-order analysis','description: Rozróżnianie UEFI/Legacy, GPT/MBR, Secure Boot, CSM, trybu kontrolera i wpisów boot managera. step: Zapisz model i objaw. Następnie sprawdź: Zapisz ustawienia przed zmianą; sprawdź wykrywanie dysku i stan partycji bez modyfikowania danych.','descriptionEn: Distinguish UEFI/Legacy, GPT/MBR, Secure Boot, CSM, controller mode and boot-manager entries. stepEn: Record the device model and symptom. Distinguish UEFI/Legacy, GPT/MBR, Secure Boot, CSM, controller mode and boot-manager entries. Use the OEM service documentation and change only one variable at a time.','',''),
('beginner:ZERO31-006','beginner','Firmware / bezpieczeństwo','Diagnostyka TPM 2.0 i Secure Boot','TPM 2.0 and Secure Boot diagnostics','description: Weryfikacja stanu TPM, trybu Secure Boot, kluczy platformy i wymagań systemu. step: Zapisz model i objaw. Następnie sprawdź: Sprawdź `tpm.msc`, msinfo32 i dokumentację UEFI; rozróżnij TPM firmware, dTPM i ustawienia platformy.','descriptionEn: Verify TPM state, Secure Boot mode, platform keys and operating-system requirements. stepEn: Record the device model and symptom. Verify TPM state, Secure Boot mode, platform keys and operating-system requirements. Use the OEM service documentation and change only one variable at a time.','',''),
('beginner:ZERO31-007','beginner','Laptop / EC','Diagnostyka kontrolera EC/KBC','Embedded Controller (EC/KBC) diagnostics','description: Rozpoznawanie objawów związanych z kontrolerem klawiatury, przyciskiem Power, ładowaniem i sekwencją startową. step: Zapisz model i objaw. Następnie sprawdź: Sprawdź złącza, przycisk, baterię, adapter i kody POST; odczyty linii EC wykonuj tylko według schematu.','descriptionEn: Recognise symptoms involving keyboard controller, power button, charging and startup sequencing. stepEn: Record the device model and symptom. Recognise symptoms involving keyboard controller, power button, charging and startup sequencing. Use the OEM service documentation and change only one variable at a time.','',''),
('beginner:ZERO31-008','beginner','Bateria / zasilanie','Ocena kondycji baterii laptopa','Laptop battery health assessment','description: Analiza pojemności projektowej i pełnego ładowania, cykli, napięcia, temperatury i komunikacji BMS. step: Zapisz model i objaw. Następnie sprawdź: Porównaj raport systemu z diagnostyką OEM, sprawdź zasilacz i zachowanie na zasilaniu sieciowym.','descriptionEn: Analyse design/full-charge capacity, cycles, voltage, temperature and BMS communication. stepEn: Record the device model and symptom. Analyse design/full-charge capacity, cycles, voltage, temperature and BMS communication. Use the OEM service documentation and change only one variable at a time.','',''),
('beginner:ZERO31-009','beginner','USB-C / PD','Analiza negocjacji USB-C Power Delivery','USB-C Power Delivery negotiation analysis','description: Rozpoznawanie ról źródła i odbiornika, komunikatów CC, profili PDO i ograniczeń kabla/adaptera. step: Zapisz model i objaw. Następnie sprawdź: Porównaj adapter, kabel e-marked, port i odbiornik; użyj miernika PD zgodnego ze specyfikacją.','descriptionEn: Identify source/sink roles, CC communication, PDO profiles and cable/adapter limitations. stepEn: Record the device model and symptom. Identify source/sink roles, CC communication, PDO profiles and cable/adapter limitations. Use the OEM service documentation and change only one variable at a time.','',''),
('beginner:ZERO31-010','beginner','USB / Thunderbolt','Diagnostyka Thunderbolt i stacji dokującej','Thunderbolt and docking-station diagnostics','description: Izolowanie problemów firmware, kabla, portu, autoryzacji, zasilania i zgodności urządzenia. step: Zapisz model i objaw. Następnie sprawdź: Sprawdź certyfikację i oznaczenia kabla, firmware docka, listę zgodności oraz zdarzenia systemowe.','descriptionEn: Isolate firmware, cable, port, authorization, power and device-compatibility issues. stepEn: Record the device model and symptom. Isolate firmware, cable, port, authorization, power and device-compatibility issues. Use the OEM service documentation and change only one variable at a time.','',''),
('beginner:ZERO31-011','beginner','USB4 / interfejsy','Testowanie portów USB4 i trybów Alt Mode','USB4 ports and Alt Mode testing','description: Weryfikacja możliwości portu: dane, wideo, zasilanie, szybkość i zgodność z urządzeniami. step: Zapisz model i objaw. Następnie sprawdź: Odczytaj specyfikację modelu, topologię kontrolera i możliwości przewodu; porównaj kilka znanych urządzeń.','descriptionEn: Verify port capabilities: data, video, power, speed and device compatibility. stepEn: Record the device model and symptom. Verify port capabilities: data, video, power, speed and device compatibility. Use the OEM service documentation and change only one variable at a time.','',''),
('beginner:ZERO31-012','beginner','NVMe / dyski','Diagnostyka temperatur i throttlingu NVMe','NVMe temperature and thermal-throttling diagnostics','description: Analiza temperatury kontrolera i NAND, throttlingu, radiatora, termopadu oraz obciążenia I/O. step: Zapisz model i objaw. Następnie sprawdź: Zapisz temperatury, throttling i log SMART; porównaj warunki przepływu powietrza i specyfikację dysku.','descriptionEn: Analyse controller/NAND temperature, throttling, heatsink, thermal pad and I/O load. stepEn: Record the device model and symptom. Analyse controller/NAND temperature, throttling, heatsink, thermal pad and I/O load. Use the OEM service documentation and change only one variable at a time.','',''),
('beginner:ZERO31-013','beginner','SATA / HDD','Analiza SMART dysków SATA i HDD','SATA and HDD SMART analysis','description: Interpretacja atrybutów, logów błędów, liczby realokacji i sektorów niestabilnych. step: Zapisz model i objaw. Następnie sprawdź: Porównaj SMART z logiem producenta i kablem SATA; odróżnij błędy interfejsu od mediów.','descriptionEn: Interpret SMART attributes, error logs, reallocated and pending sectors. stepEn: Record the device model and symptom. Interpret SMART attributes, error logs, reallocated and pending sectors. Use the OEM service documentation and change only one variable at a time.','',''),
('beginner:ZERO31-014','beginner','Odzyskiwanie danych','Plan bezpiecznego obrazowania nośnika','Safe storage imaging and recovery planning','description: Plan pracy z niestabilnym HDD/SSD: priorytety, obraz sektorowy, logi i kopia robocza. step: Zapisz model i objaw. Następnie sprawdź: Oceń, czy nośnik jest mechanicznie stabilny; ustal priorytet danych i ogranicz niepotrzebne uruchomienia.','descriptionEn: Plan work on unstable HDD/SSD: priorities, sector image, logs and working copy. stepEn: Record the device model and symptom. Plan work on unstable HDD/SSD: priorities, sector image, logs and working copy. Use the OEM service documentation and change only one variable at a time.','',''),
('beginner:ZERO31-015','beginner','BitLocker / dane','Obsługa klucza odzyskiwania BitLocker','BitLocker recovery-key handling','description: Identyfikacja przyczyny recovery prompt po zmianie BIOS, TPM, płyty, Secure Boot lub boot managera. step: Zapisz model i objaw. Następnie sprawdź: Nie resetuj TPM; ustal identyfikator klucza, właściciela urządzenia i wcześniejsze zmiany.','descriptionEn: Identify why recovery appears after BIOS, TPM, board, Secure Boot or boot-manager changes. stepEn: Record the device model and symptom. Identify why recovery appears after BIOS, TPM, board, Secure Boot or boot-manager changes. Use the OEM service documentation and change only one variable at a time.','',''),
('beginner:ZERO31-016','beginner','Windows / WinRE','Naprawa środowiska odzyskiwania WinRE','Windows Recovery Environment (WinRE) repair','description: Analiza stanu WinRE, lokalizacji obrazu, partycji odzyskiwania i dostępnych opcji naprawy. step: Zapisz model i objaw. Następnie sprawdź: Zapisz status `reagentc /info`, układ partycji i komunikaty; sprawdź szyfrowanie oraz kopię danych.','descriptionEn: Analyse WinRE state, image location, recovery partition and available repair options. stepEn: Record the device model and symptom. Analyse WinRE state, image location, recovery partition and available repair options. Use the OEM service documentation and change only one variable at a time.','',''),
('beginner:ZERO31-017','beginner','Windows / BCD','Diagnostyka BCD i Windows Boot Manager','BCD and Windows Boot Manager diagnostics','description: Rozpoznawanie problemów wpisu boot, partycji EFI, kolejności rozruchu i plików systemowych. step: Zapisz model i objaw. Następnie sprawdź: Ustal UEFI/GPT, wykrywanie dysku i stan partycji EFI; nie wykonuj zapisu przed rozpoznaniem dysku.','descriptionEn: Identify boot-entry, EFI system partition, boot order and system-file problems. stepEn: Record the device model and symptom. Identify boot-entry, EFI system partition, boot order and system-file problems. Use the OEM service documentation and change only one variable at a time.','',''),
('beginner:ZERO31-018','beginner','Windows / sterowniki','Diagnostyka konfliktu sterowników','Windows driver conflict diagnostics','description: Weryfikacja identyfikatora sprzętu, wersji, podpisu, źródła i historii sterownika. step: Zapisz model i objaw. Następnie sprawdź: Zapisz hardware ID i kod błędu; sprawdź sterownik OEM oraz zdarzenia przed i po zmianie.','descriptionEn: Verify hardware ID, version, signature, source and driver history. stepEn: Record the device model and symptom. Verify hardware ID, version, signature, source and driver history. Use the OEM service documentation and change only one variable at a time.','',''),
('beginner:ZERO31-019','beginner','Windows / BSOD','Analiza minidump i BSOD','Minidump and BSOD analysis','description: Korelacja bugcheck, modułu, czasu, sterownika i historii zmian; rozróżnianie objawu od winowajcy. step: Zapisz model i objaw. Następnie sprawdź: Zabezpiecz pliki dump, odczytaj kod i stack w WinDbg; porównaj kilka zdarzeń, nie tylko jeden moduł.','descriptionEn: Correlate bugcheck, module, time, driver and change history; distinguish symptom from cause. stepEn: Record the device model and symptom. Correlate bugcheck, module, time, driver and change history; distinguish symptom from cause. Use the OEM service documentation and change only one variable at a time.','',''),
('beginner:ZERO31-020','beginner','Windows / WHEA','Diagnostyka błędów WHEA i PCIe','WHEA and PCIe error diagnostics','description: Interpretacja WHEA Logger, AER, link retraining i błędów urządzeń PCIe. step: Zapisz model i objaw. Następnie sprawdź: Zapisz source, bank, APIC ID, PCIe BDF i czas; porównaj z temperaturą, BIOS i konfiguracją.','descriptionEn: Interpret WHEA Logger, AER, link retraining and PCIe device errors. stepEn: Record the device model and symptom. Interpret WHEA Logger, AER, link retraining and PCIe device errors. Use the OEM service documentation and change only one variable at a time.','',''),
('beginner:ZERO31-021','beginner','Windows / zdarzenia','Czytanie Podglądu zdarzeń i Reliability Monitor','Event Viewer and Reliability Monitor analysis','description: Filtrowanie zdarzeń systemowych, aplikacyjnych i sprzętowych w osi czasu. step: Zapisz model i objaw. Następnie sprawdź: Skoreluj zdarzenia z godziną objawu, źródłem, identyfikatorem, kodem i aktualizacjami.','descriptionEn: Filter system, application and hardware events on a timeline. stepEn: Record the device model and symptom. Filter system, application and hardware events on a timeline. Use the OEM service documentation and change only one variable at a time.','',''),
('beginner:ZERO31-022','beginner','Windows / DISM','Naprawa obrazu Windows przy użyciu DISM i SFC','Repairing Windows image with DISM and SFC','description: Kolejność kontroli komponent store, źródła naprawy, integralności plików i logów. step: Zapisz model i objaw. Następnie sprawdź: Zapisz edition/build, status DISM, kod zakończenia i CBS.log; upewnij się, że źródło pasuje do wersji.','descriptionEn: Sequence component-store, repair-source, system-file and log checks. stepEn: Record the device model and symptom. Sequence component-store, repair-source, system-file and log checks. Use the OEM service documentation and change only one variable at a time.','',''),
('beginner:ZERO31-023','beginner','RAM / DDR5','Test stabilności RAM DDR5 i profili XMP/EXPO','DDR5 RAM and XMP/EXPO stability testing','description: Rozdzielenie problemu modułu, slotu, kontrolera, treningu pamięci i profilu OC. step: Zapisz model i objaw. Następnie sprawdź: Testuj ustawienia JEDEC, pojedynczy moduł, sloty według manuala i wersję BIOS.','descriptionEn: Separate DIMM, slot, controller, memory training and overclock-profile issues. stepEn: Record the device model and symptom. Separate DIMM, slot, controller, memory training and overclock-profile issues. Use the OEM service documentation and change only one variable at a time.','',''),
('beginner:ZERO31-024','beginner','RAM / diagnostyka','Rozróżnianie błędu DIMM i slotu pamięci','Distinguishing DIMM and memory-slot faults','description: Krzyżowe testy modułów i slotów z zapisem konfiguracji oraz kodów POST. step: Zapisz model i objaw. Następnie sprawdź: Oznacz moduły A/B i sloty; sprawdź listę QVL, osadzenie oraz sygnały POST.','descriptionEn: Cross-test DIMMs and slots while recording configuration and POST codes. stepEn: Record the device model and symptom. Cross-test DIMMs and slots while recording configuration and POST codes. Use the OEM service documentation and change only one variable at a time.','',''),
('beginner:ZERO31-025','beginner','RAM / platforma','Diagnostyka kontrolera pamięci CPU','CPU integrated memory controller diagnostics','description: Analiza błędów zależnych od kanału, obciążenia, socketu, montażu CPU i firmware. step: Zapisz model i objaw. Następnie sprawdź: Porównaj QVL, sloty zalecane przez producenta i konfigurację minimalną; sprawdź socket pod powiększeniem.','descriptionEn: Analyse channel-dependent errors, loading, socket, CPU mounting and firmware. stepEn: Record the device model and symptom. Analyse channel-dependent errors, loading, socket, CPU mounting and firmware. Use the OEM service documentation and change only one variable at a time.','',''),
('beginner:ZERO311-001','beginner','Płyta główna / sekwencja zasilania','Rozpoznawanie sekwencji zasilania płyty laptopa','Laptop motherboard power-sequence analysis','description: Prześledź tor od DC-IN/USB-C przez ładowarkę, zabezpieczenia, linie always-on, sygnały enable i power-good, aż po stany S0. Wartości i nazwy sygnałów zależą od konkretnej płyty. step: Zapisz objaw, czas do wyłączenia i stan diod. Zidentyfikuj adapter, port wejściowy i jego parametry znamionowe.','descriptionEn: Trace the path from DC input or USB-C through charging, protection, always-on rails, enable and power-good signals, and finally the S0 state. Signal names and voltage limits are board-specific. stepEn: Record the symptom, time to shutdown and LED state. Identify the adapter, input port and rated specifications.','',''),
('beginner:ZERO311-002','beginner','Bateria / kontroler ładowania','Analiza układu ładowania i kontrolera baterii','Battery charger and fuel-gauge controller analysis','description: Oddziel problem adaptera, portu, toru wejściowego, kontrolera ładowania, pakietu, BMS i komunikacji SMBus. Kondycja ogniw nie jest tym samym co zdolność ładowania. step: Sprawdź obudowę pakietu, temperaturę i oznaki deformacji. Zweryfikuj zgodność adaptera z wymaganiami modelu.','descriptionEn: Separate adapter, port, input path, charger controller, battery pack, BMS and SMBus communication faults. Cell health is not the same as charging functionality. stepEn: Inspect the pack enclosure, temperature and signs of deformation. Verify adapter compatibility with the model requirements.','',''),
('beginner:ZERO311-003','beginner','Laptop / sygnały sterujące','Diagnostyka sygnału PWRBTN, LID i czujników laptopa','Laptop PWRBTN, lid-switch and sensor diagnostics','description: Przyczyną może być przycisk, taśma, czujnik Halla, magnes, ustawienia ACPI, firmware EC lub sterownik. Objaw zależy od konstrukcji modelu. step: Sprawdź konfigurację przycisku i zachowanie pokrywy w systemie. Wykonaj diagnostykę OEM i odczytaj zdarzenia ACPI/Power.','descriptionEn: Possible causes include the button, cable, Hall sensor, magnet, ACPI settings, EC firmware or driver. Behaviour depends on the model design. stepEn: Check power-button and lid-action settings in the OS. Run OEM diagnostics and review ACPI/Power events.','',''),
('beginner:ZERO311-004','beginner','Audio / cyfrowy tor dźwięku','Diagnostyka toru audio HDMI, DisplayPort i USB','HDMI, DisplayPort and USB audio path diagnostics','description: Oddziel urządzenie wyjściowe, profil systemu, sterownik GPU/audio, EDID, kabel i firmware stacji. HDMI/DP może udostępniać osobne urządzenie audio. step: Sprawdź, czy właściwe wyjście jest wybrane jako domyślne. Zweryfikuj wyciszenie systemu, aplikacji i monitora.','descriptionEn: Separate output device, OS profile, GPU/audio driver, EDID, cable and dock firmware. HDMI/DP can expose a separate audio endpoint. stepEn: Check whether the intended output is selected as default. Check system, application and monitor mute settings.','',''),
('beginner:ZERO311-005','beginner','PCIe / magistrala','Diagnostyka magistrali PCI Express i urządzeń końcowych','PCI Express link and endpoint diagnostics','description: Sprawdź generację, szerokość łącza, topologię, bifurkację, slot, riser, ustawienia firmware oraz błędy korekcyjne. Negocjowana prędkość zależy od obu końców i jakości toru. step: Odczytaj szerokość i generację linku w narzędziu diagnostycznym. Zbierz błędy WHEA i zdarzenia systemowe.','descriptionEn: Check generation, link width, topology, bifurcation, slot, riser, firmware settings and corrected errors. Negotiated speed depends on both endpoints and signal integrity. stepEn: Read negotiated link width and generation with a diagnostic tool. Collect WHEA errors and system events.','',''),
('beginner:ZERO311-006','beginner','Elektronika / inspekcja','Ocena kondycji kondensatorów i śladów przegrzania','Capacitor condition and thermal-damage inspection','description: Oględziny mogą ujawnić pęknięcia, wybrzuszenie, wyciek, odbarwienia laminatu lub nadpalone złącza. Sam wygląd nie potwierdza wszystkich awarii kondensatorów. step: Odłącz źródła zasilania i postępuj zgodnie z procedurą rozładowania. Sprawdź wybrzuszenia, pęknięcia, wyciek i ślady termiczne.','descriptionEn: Inspection may reveal cracks, bulging, leakage, PCB discolouration or burnt connectors. Appearance alone cannot confirm every capacitor failure. stepEn: Disconnect power sources and follow the approved discharge procedure. Inspect for bulging, cracks, leakage and thermal marks.','',''),
('beginner:ZERO311-007','beginner','Firmware / reset','Diagnostyka resetów i watchdog w firmware','Firmware watchdog and unexpected-reset diagnostics','description: Reset może wynikać z watchdog, zasilania, temperatury, błędu firmware, sterownika lub sprzętowego fault. Ustal, czy reset poprzedza BSOD, czy następuje bez niego. step: Sprawdź temperaturę i zachowanie zasilacza. Odczytaj zdarzenia Kernel-Power, WHEA i BugCheck.','descriptionEn: A reset may result from a watchdog, power, thermal, firmware, driver or hardware fault. Determine whether a BSOD precedes it or the reset occurs without one. stepEn: Check temperatures and power-supply behaviour. Review Kernel-Power, WHEA and BugCheck events.','',''),
('beginner:ZERO311-008','beginner','RAM / ECC / RAS','Diagnostyka błędów pamięci ECC i raportowania RAS','ECC memory and RAS event diagnostics','description: Rozróżnij corrected, uncorrected, patrol scrub, channel, DIMM i zdarzenia kontrolera. Zależnie od platformy raportowanie odbywa się przez BMC, firmware i dzienniki systemowe. step: Odczytaj logi BMC/SEL i RAS. Powiąż zdarzenie z konkretnym slotem i numerem DIMM.','descriptionEn: Distinguish corrected, uncorrected, patrol-scrub, channel, DIMM and controller events. Reporting may use BMC, firmware and OS logs depending on the platform. stepEn: Review BMC/SEL and RAS logs. Map the event to the specific slot and DIMM identifier.','',''),
('beginner:ZERO311-009','beginner','Storage / NAS / RAID','Diagnostyka dysku sieciowego NAS i RAID degradacji','NAS storage and degraded RAID diagnostics','description: Ustal poziom RAID, liczbę awarii dopuszczalnych, status kontrolera, SMART, błędy linku, zasilanie i temperaturę. Degraded nie jest zgodą na wymuszoną inicjalizację. step: Wykonaj kopię konfiguracji NAS. Odczytaj SMART i dziennik kontrolera.','descriptionEn: Identify RAID level, fault tolerance, controller status, SMART, link errors, power and temperature. A degraded state is not permission to force-initialize. stepEn: Export a backup of the NAS configuration. Read SMART and controller logs.','',''),
('beginner:ZERO311-010','beginner','CPU / wydajność','Analiza wydajności CPU: zegary, limity i pobór mocy','CPU performance: clocks, limits and power behaviour','description: Rozróżnij limit termiczny, mocy, prądu, firmware, planu zasilania i ograniczenie platformy. Maksymalny boost nie jest stałą gwarantowaną częstotliwością. step: Uruchom jeden powtarzalny test CPU. Rejestruj zegary efektywne, temperatury i limity.','descriptionEn: Distinguish thermal, power, current, firmware, power-plan and platform limits. Maximum boost is not a guaranteed sustained frequency. stepEn: Run one repeatable CPU test. Record effective clocks, temperatures and limit flags.','',''),
('beginner:ZERO311-011','beginner','GPU / VRAM','Diagnostyka pamięci VRAM i testy artefaktów GPU','GPU VRAM diagnostics and artifact testing','description: Oddziel pamięć VRAM, rdzeń GPU, sterownik, temperaturę hotspot, zasilanie, kabel i monitor. Artefakt widoczny na zrzucie ekranu wskazuje inny tor niż artefakt wyłącznie na fizycznym wyświetlaczu. step: Sprawdź kabel, monitor i inne wyjście. Porównaj zrzut ekranu z fotografią ekranu.','descriptionEn: Separate VRAM, GPU core, hotspot temperature, driver, power, cable and monitor. An artifact captured in a screenshot indicates a different path from one visible only on the physical display. stepEn: Check cable, monitor and another output. Compare a screenshot with a photo of the display.','',''),
('beginner:ZERO311-012','beginner','Monitor / obraz','Diagnostyka monitora: EDID, HDR i profil kolorów','Monitor diagnostics: EDID, HDR and colour profile','description: Sprawdź EDID, kabel, wejście, przepustowość, tryb GPU, ustawienia OSD, HDR i profil ICC. EDID może być ograniczony przez adapter, KVM lub stację. step: Odczytaj tryby obsługiwane przez EDID. Sprawdź kabel, adapter, KVM i port.','descriptionEn: Check EDID, cable, input, bandwidth, GPU mode, OSD settings, HDR and ICC profile. EDID can be limited by an adapter, KVM or dock. stepEn: Read modes reported by EDID. Check cable, adapter, KVM and port.','',''),
('beginner:ZERO311-013','beginner','USB / kontroler','Diagnostyka kontrolera USB i zasilania portów','USB host controller and port power diagnostics','description: Rozróżnij awarię pojedynczego gniazda, grupy portów, kontrolera, zasilania VBUS, kabla, urządzenia i sterownika chipsetu. step: Sprawdź ten sam zestaw na innym komputerze. Porównaj porty z różnych grup i kontrolerów.','descriptionEn: Distinguish a single connector, port group, controller, VBUS power, cable, device and chipset-driver fault. stepEn: Test the same combination on another computer. Compare ports from different groups and controllers.','',''),
('beginner:ZERO311-014','beginner','Linux / diagnostyka','Analiza dzienników Linux: journalctl, dmesg i systemd','Linux logs: journalctl, dmesg and systemd analysis','description: Zbierz dziennik rozruchu, komunikaty jądra, status systemd, wersję kernela i identyfikatory urządzeń. Powiąż wpisy z czasem awarii. step: Sprawdź status usługi przez systemctl status. Odczytaj journalctl z zakresem czasu awarii.','descriptionEn: Collect boot journal, kernel messages, systemd status, kernel version and device identifiers. Correlate entries with the failure time. stepEn: Check service status with systemctl status. Read journalctl for the failure time window.','','');
